import json, subprocess
req = json.load(open('examples/mapped.compile.json'))
exp = json.load(open('examples/mapped.image.json'))
p = subprocess.run(['./submit/run'], input=json.dumps(req)+'\n', text=True, capture_output=True)
got = json.loads(p.stdout)
def find(o, path=""):
    if isinstance(o, dict):
        for k in o:
            find(o[k], path+"/"+str(k))
    elif isinstance(o, list):
        for i,v in enumerate(o):
            find(v, path+"/%d"%i)
    else:
        if got_get(path) != o:
            print("DIFF at", path, "got", got_get(path), "exp", o)
def got_get(path):
    cur = got
    for p in path.split('/')[1:]:
        cur = cur[int(p)] if p.isdigit() else cur[p]
    return cur
find(exp)
